CREATE    VIEW [FO].[vwCustTable]
AS
SELECT 
	T1.ACCOUNTNUM
	,T1.PARTYCOUNTRY AS PARTYCOUNTRY
	,T1.BLOCKED AS ONHOLDSTATUS
	,T1.PAYMMODE AS PAYMENTMETHOD
	,T1.BANKACCOUNT AS PAYMENTBANKACCOUNT
	,T1.RECID AS RECIDCUSTTABLE
	,T1.CUSTGROUP
	,T1.CURRENCY AS CURRENCY
	,T1.PARTY AS PARTYID
	,T1.PAYMMODE AS PAYMMODE
	,T1.TAXGROUP AS TAXGROUP
	,T1.MODIFIEDDATETIME AS MODIFIEDDATETIME
	,T1.MODIFIEDBY AS MODIFIEDBY
	,T1.CREATEDDATETIME AS CREATEDDATETIME
	,T1.DATAAREAID AS DATAAREAID
	,T1.PARTITION AS PARTITION
	,T1.RECID AS RECID

	,T5.PARTYTYPE AS PARTYTYPE
	,T5.NAME
	,T5.PARTYNUMBER AS PARTYNUMBER
	,T13.CITY
	,T18.ZIPCODE
	,T18.COUNTRYREGIONID 
	,CASE
		WHEN T1.[BLOCKED] = 0 THEN 'No'
		WHEN T1.[BLOCKED] = 1 THEN 'Invoice'
		WHEN T1.[BLOCKED] = 2 THEN 'All'
		WHEN T1.[BLOCKED] = 3 THEN 'Payment'
		WHEN T1.[BLOCKED] = 4 THEN 'Requisition'
		WHEN T1.[BLOCKED] = 5 THEN 'Never'
	END AS [ONHOLDSTATUS_Description]
FROM [synapse_fo].[CUSTTABLE] T1
/*
LEFT OUTER JOIN [synapse_fo].[CUSTCOLLECTIONSCONTACT] T2 ON (
		(
			(T1.ACCOUNTNUM = T2.ACCOUNTNUM)
			AND (T1.DATAAREAID = T2.DATAAREAID)
			)
		AND (T1.PARTITION = T2.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[WHSCUSTTABLE] T3 ON (
		(
			(T1.ACCOUNTNUM = T3.ACCOUNTNUM)
			AND (T1.DATAAREAID = T3.DATAAREAID)
			)
		AND (T1.PARTITION = T3.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[RETAILCUSTTABLE] T4 ON (
		(
			(T1.ACCOUNTNUM = T4.ACCOUNTNUM)
			AND (T1.DATAAREAID = T4.DATAAREAID)
			)
		AND (T1.PARTITION = T4.PARTITION)
		)
*/
CROSS JOIN [synapse_fo].[DIRPARTYBASEENTITY_RICS] T5
/*
LEFT OUTER JOIN [synapse_fo].[COMPANYNAFCODE] T6 ON (
		(
			(T1.COMPANYNAFCODE = T6.RECID)
			AND (T1.DATAAREAID = T6.DATAAREAID)
			)
		AND (T1.PARTITION = T6.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[TAXGSTRELIEFGROUPHEADING_MY] T7 ON (
		(
			(T1.TAXGSTRELIEFGROUPHEADING_MY = T7.RECID)
			AND (T1.DATAAREAID = T7.DATAAREAID)
			)
		AND (T1.PARTITION = T7.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[DIMENSIONSETENTITY_RICS] T8 ON (
		(T1.DEFAULTDIMENSION = T8.RECID)
		AND (T1.PARTITION = T8.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[TAXINFORMATIONCUSTTABLE_IN] T9 ON (
		(
			(T1.ACCOUNTNUM = T9.CUSTTABLE)
			AND (T1.DATAAREAID = T9.DATAAREAID)
			)
		AND (T1.PARTITION = T9.PARTITION)
		)
--LEFT OUTER JOIN [synapse_fo].[CUSTWRITEOFFFINANCIALREASONSSETUPENTITY] T10 ON (
--		(T1.CUSTWRITEOFFREFRECID = T10.RECID)
--		AND (T1.PARTITION = T10.PARTITION)
--		)
LEFT OUTER JOIN [synapse_fo].[MCRCUSTTABLE] T11 ON (
		(
			(T1.RECID = T11.CUSTTABLE)
			AND (T1.DATAAREAID = T11.DATAAREAID)
			)
		AND (T1.PARTITION = T11.PARTITION)
		)
LEFT OUTER JOIN [synapse_fo].[WHSFULFILLMENTPOLICY] T12 ON (
		(
			(T3.FULFILLMENTPOLICY = T12.RECID)
			AND (T3.DATAAREAID = T12.DATAAREAID)
			)
		AND (T3.PARTITION = T12.PARTITION)
		)
*/
LEFT OUTER JOIN [synapse_fo].[LOGISTICSPOSTALADDRESSBASEENTITY_RICS] T13 ON (
		(
			(T5.PRIMARYADDRESSLOCATION = T13.LOCATIONRECID)
			AND (T5.PARTITION = T13.PARTITION)
			)
		AND (
			(
				T13.VALIDFROM <= GETUTCDATE()
				)
			AND (
				T13.VALIDTO >= GETUTCDATE()
				)
			)
		)
/*
LEFT OUTER JOIN [synapse_fo].[CUSTDEFAULTROLELOCATION] T14 ON (
		(
			(
				(
					(T1.ACCOUNTNUM = T14.ACCOUNTNUM)
					AND (T1.DATAAREAID = T14.DATAAREAID)
					)
				AND (T1.PARTITION = T14.PARTITION)
				)
			AND (
				(T5.RECID = T14.PARTY)
				AND (T5.PARTITION = T14.PARTITION)
				)
			)
		AND (T14.TYPE = 2)
		)
*/
LEFT OUTER JOIN [synapse_fo].[CUSTDEFAULTROLELOCATION_RICS] T15 ON (
		(
			(
				(
					(T1.ACCOUNTNUM = T15.ACCOUNTNUM)
					AND (T1.DATAAREAID = T15.DATAAREAID)
					)
				AND (T1.PARTITION = T15.PARTITION)
				)
			AND (
				(T5.RECID = T15.PARTY)
				AND (T5.PARTITION = T15.PARTITION)
				)
			)
		AND (T15.TYPE = 1)
		)
/*
LEFT OUTER JOIN [synapse_fo].[LOGISTICSLOCATIONEXT] T16 ON (
		(
			(T13.RECID = T16.LOCATION)
			AND (T13.PARTITION = T16.PARTITION)
			)
		AND (T16.DATAAREAID = T1.DATAAREAID)
		)
LEFT OUTER JOIN [synapse_fo].[LOGISTICSPOSTALADDRESSBASEENTITY_RICS] T17 ON (
		(
			(T14.LOGISTICSLOCATION = T17.LOCATIONRECID)
			AND (T14.PARTITION = T17.PARTITION)
			)
		AND (
			(
				T17.VALIDFROM <= GETUTCDATE()
				)
			AND (
				T17.VALIDTO >= GETUTCDATE()
